function meterMeasurementSignalContext(payload){
 const body=Object.assign({},payload||{});
 body.observer=meterChromaticityObserver();
 body.signal_mode=getVal('signal_mode')||'sdr';
 if(body.signal_mode==='dv'){
  const dvTransport=dvTransportDefaults(getVal('dv_transport'));
  body.target_gamma=meterDvAutoTargetGamma();
  body.dv_map_mode=getVal('dv_map_mode')||((config&&config.dv_map_mode)||'2');
  body.dv_transport=dvTransport.dv_transport;
  body.dv_interface=dvTransport.dv_interface;
 }
 body.max_luma=(document.getElementById('max_luma')||{}).value||((config&&config.max_luma)||'1000');
 body.min_luma=meterHdrMetadataFieldValue('min_luma')||((config&&config.min_luma)||'0.005');
 body.max_cll=meterHdrMetadataFieldValue('max_cll')||((config&&config.max_cll)||body.max_luma);
 body.max_fall=meterHdrMetadataFieldValue('max_fall')||((config&&config.max_fall)||'400');
 if(body.measurement_meter_port==null){
  const measurementPort=meterSelectedMeasurementPort();
  if(measurementPort) body.measurement_meter_port=measurementPort;
 }
 if(body.measurement_meter_usb_id==null&&body.measurement_meter_port!=null){
  // Pin the read to the physical meter, not just its spotread index: the
  // -c index is enumeration order and silently shifts when meters are
  // plugged/unplugged, which made a stale index land on the WRONG meter
  // (e.g. the colorimeter despite the spectro being selected). The scripts
  // resolve the current index from this usb_id at read time.
  const selectedMeter=meterFindByPort(body.measurement_meter_port);
  if(selectedMeter&&selectedMeter.usb_id) body.measurement_meter_usb_id=String(selectedMeter.usb_id);
 }
 if(body.profiling_meter_port==null){
  const profilingPort=meterSelectedProfilingPort();
  if(profilingPort) body.profiling_meter_port=profilingPort;
 }
 // Use the COMMITTED (applied) range, not the live dropdown. The server
 // applies transport_signal_range to the wire on every patch push and
 // restarts the renderer when it changes; sourcing the live dropdown here
 // meant that changing the Range dropdown DURING a continuous read leaked the
 // new range each iteration and restarted PGenerator before the operator
 // clicked Apply & Restart. New single reads are gated on settings being
 // applied (so committed==dropdown there), and the range only reaches the wire
 // via Apply & Restart. Fall back to the dropdown only before the first config
 // load populates `config`.
 const committedRange=(typeof config!=='undefined'&&config&&config.rgb_quant_range!=null&&String(config.rgb_quant_range)!=='')
  ? String(config.rgb_quant_range)
  : getVal('rgb_quant_range');
 if(body.signal_range==null) body.signal_range=committedRange;
 if(body.transport_signal_range==null) body.transport_signal_range=committedRange;
 if(body.color_format==null) body.color_format=getVal('color_format')||((config&&config.color_format)||'0');
 if(body.colorimetry==null) body.colorimetry=getVal('colorimetry')||((config&&config.colorimetry)||'0');
 if(body.primaries==null) body.primaries=getVal('primaries')||((config&&config.primaries)||'0');
  // CCSS override: only inject when the caller didn't already pass one.
  // The wizard / meterRunSeries pass `ccss_override` explicitly via the
  // pendingConfig snapshot; single reads / autocal reads fall through to
  // the current main-control value. Empty token => server uses the
  // technology default. The display_type token is whatever the caller set
  // (tech key, since we redirected getEffectiveDisplayType() to the tech
  // dropdown). ccss_override is independent — it's the CCSS file.
  if(body.ccss_override==null){
   const override=(typeof getCcssOverride==='function')?getCcssOverride():'';
   if(override) body.ccss_override=override;
  }
   if(meterTargetWhitePointEnabled()){
    body.custom_d65_enabled=true;
    body.target_white_x=(document.getElementById('meterTargetWhiteX')||{}).value||'';
    body.target_white_y=(document.getElementById('meterTargetWhiteY')||{}).value||'';
   }
  // Target White / Target Black overrides for read/series/autocal target math.
  try{ Object.assign(body,meterTargetLevelsPayload()); }catch(e){}
 return body;
}

const METER_AUTOCAL_STANDARD_OBSERVER='1931_2';
function meterAutoCalMeasurementSignalContext(payload){
 const body=meterMeasurementSignalContext(payload);
 // LG calibration targets and gamut coordinates are standardized in the
 // CIE 1931 2-degree observer. Keep every AutoCal read in that same observer
 // even when the analysis workspace is displaying an alternate observer.
 body.observer=METER_AUTOCAL_STANDARD_OBSERVER;
 return body;
}

function meterLgAutoCalRequestedSignalMode(){
 const mode=String((meterChartSignalMode&&meterChartSignalMode())||'sdr').toLowerCase();
 return mode==='hdr10'?'hdr10':'sdr';
}

function meterAutoCalTargetGammaValue(){
 // Honor the operator's TARGET GAMMA dropdown. The previous code hardcoded
 // 'st2084' for HDR10, which overrode the dropdown whenever the operator
 // wanted a 2.2 power-gamma chart view and silently forced PQ target lines.
 // Fall back to a mode-appropriate default only when the dropdown is empty
 // (first paint before any user selection).
 const el=document.getElementById('meterTargetGamma');
 const selected=String((el&&el.value) || '');
 if(selected) return selected;
 // DV pre/post verification reports grade against PQ (st2084) just like
 // HDR10, so the empty-dropdown fallback must include dv alongside hdr10
 // (meterLgAutoCalRequestedSignalMode() collapses dv->'sdr' -- read live).
 const requested=String((typeof getVal==='function'?getVal('signal_mode'):'')||'').toLowerCase();
 return (requested==='hdr10'||requested==='dv')?'st2084':'bt1886';
}

function meterLgAutoCalGreyscaleTargetGammaValue(){
 // LG HDR autocal always calibrates against a 2.2 power target; Dolby Vision
 // greyscale reuses the same HDR20 1D-DPG mechanism and must ALSO always
 // calibrate against 2.2, regardless of whatever the Target Gamma dropdown
 // shows (operator-reported bug 2026-07-24: meterLgAutoCalRequestedSignalMode()
 // collapses dv->'sdr', so this used to fall through to the dropdown's raw
 // value -- meaning DV greyscale calibrated against whatever gamma was left
 // selected from a prior SDR/HDR10 run instead of always pinning 2.2). SDR
 // series honor the dropdown like meterAutoCalTargetGammaValue().
 const dvSignal=(String((typeof getVal==='function'?getVal('signal_mode'):'')||'').toLowerCase()==='dv');
 return (dvSignal||meterLgAutoCalRequestedSignalMode()==='hdr10')?'2.2':meterAutoCalTargetGammaValue();
}

function meterAutoCalTargetGamutValue(){
 // HDR10 + DV AutoCal / post-cal series solve in the P3-D65 target gamut
 // (consumer content is mastered to P3). Read the LIVE signal_mode because
 // meterLgAutoCalRequestedSignalMode() collapses dv->'sdr' and used to force
 // DV through the SDR bt709 fallback.
 const live=String((typeof getVal==='function'?getVal('signal_mode'):'')||'').toLowerCase();
 if(live==='hdr10'||live==='dv'||meterLgAutoCalRequestedSignalMode()==='hdr10') return 'p3d65';
 if(live==='hlg') return 'bt2020';
 const raw=String((document.getElementById('meterTargetGamut')||{}).value||'auto').toLowerCase();
 if(raw==='bt709'||raw==='bt2020'||raw==='p3d65'||raw==='p3dci') return raw;
 return 'bt709';
}

function meterAutoCalUseFullDdcSpine(){
 // DV greyscale uses the same HDR20 20-point DDC ladder as HDR10 (the
 // collapse in meterLgAutoCalRequestedSignalMode() used to return false for
 // dv and the wizard skipped the spine -- read the live signal mode).
 const requested=String((typeof getVal==='function'?getVal('signal_mode'):'')||'').toLowerCase();
 return requested==='sdr'||requested==='hdr10'||requested==='dv';
}

function meterEnsureAppliedGeneratorSettings(){
 if(!meterEnsureExtendedVideoTransport()) return false;
 if(!hasUnsavedSettings()) return true;
 const applyBar=document.getElementById('applyBar');
 if(applyBar&&applyBar.scrollIntoView){
  try{ applyBar.scrollIntoView({behavior:'smooth',block:'center'}); }catch(e){ applyBar.scrollIntoView(); }
 }
 toast('Apply & Restart before taking meter readings so the generator mode matches the chart targets',true);
 return false;
}

function meterLgAutoCalTransportReady(){
 // DV's proven "standard" transport is 8-bit RGB Full (color_format=0,
 // max_bpc=8, rgb_quant_range=2, primaries=1) -- a DIFFERENT wire transport
 // than HDR10's 10-bit YCbCr444 Limited (primaries=2). See
 // normalize_dv_transport_conf() in command.pm for the authoritative values
 // (operator-reported 2026-07-24: DV AutoCal was gated on the HDR10
 // transport and never became "ready"). Read the live signal mode.
 const requested=String((typeof getVal==='function'?getVal('signal_mode'):'')||'').toLowerCase();
 if(requested==='dv'){
  return getVal('signal_mode')==='dv'
   && getVal('max_bpc')==='8'
   && getVal('color_format')==='0'
   && getVal('rgb_quant_range')==='2'
   && getVal('colorimetry')==='9'
   && getVal('primaries')==='1'
   && getVal('eotf')==='2';
 }
 const hdrRequest=(requested==='hdr10');
 const base=getVal('signal_mode')===requested
  && getVal('max_bpc')==='10'
  && getVal('color_format')==='1'
  && getVal('rgb_quant_range')==='1';
 if(!base) return false;
 if(hdrRequest){
  return getVal('colorimetry')==='9'&&getVal('primaries')==='2'&&getVal('eotf')==='2';
 }
 return getVal('colorimetry')==='2'&&getVal('eotf')==='0';
}

function meterLgAutoCalTransportAvailable(){
 const modeIdx=getVal('mode_idx');
 const validFmts=getValidFormats(modeIdx,10);
 const validBpc=getValidBpc(modeIdx,1);
 return validFmts.indexOf(1)>=0 && validBpc.indexOf(10)>=0;
}

function meterSetLgAutoCalTransportValues(){
 // DV's proven "standard" transport is 8-bit RGB Full (primaries=1) -- a
 // DIFFERENT wire transport than HDR10's 10-bit YCbCr444 Limited
 // (primaries=2). See normalize_dv_transport_conf() in command.pm for the
 // authoritative values (operator-reported 2026-07-24: DV AutoCal was
 // pushing the HDR10 transport instead). Read the live signal mode.
 const requested=String((typeof getVal==='function'?getVal('signal_mode'):'')||'').toLowerCase();
 setVal('signal_mode',requested);
 if(requested==='dv'){
  setVal('eotf','2');
  setVal('primaries','1');
  setVal('colorimetry','9');
  setVal('max_bpc','8');
  setVal('color_format','0');
  setVal('rgb_quant_range','2');
  applyMeterTargetGamutDefault(true);
  applyMeterTargetGammaDefault();
  updateModeVisibility();
  updateDropdowns();
  setVal('max_bpc','8');
  setVal('color_format','0');
  setVal('rgb_quant_range','2');
  setVal('colorimetry','9');
  setVal('eotf','2');
  setVal('primaries','1');
  checkSettingsChanged();
  saveMeterSettings();
  return;
 }
 const hdrRequest=(requested==='hdr10');
 if(hdrRequest){
  setVal('eotf','2');
  setVal('primaries','2');
  setVal('colorimetry','9');
 }else{
  setVal('eotf','0');
  setVal('primaries','0');
  setVal('colorimetry','2');
 }
 setVal('max_bpc','10');
 setVal('color_format','1');
 setVal('rgb_quant_range','1');
 applyMeterTargetGamutDefault(true);
 applyMeterTargetGammaDefault();
 updateModeVisibility();
 updateDropdowns();
 setVal('max_bpc','10');
 setVal('color_format','1');
 setVal('rgb_quant_range','1');
 if(hdrRequest){
  setVal('colorimetry','9');
  setVal('eotf','2');
  setVal('primaries','2');
 }else{
  setVal('colorimetry','2');
  setVal('eotf','0');
  setVal('primaries','0');
 }
 checkSettingsChanged();
 saveMeterSettings();
}

async function meterEnsureLgAutoCalTransport(workflowName){
 // Popup block removed by user request on 2026-06-13: see the comment
 // on meterEnsureExtendedVideoTransport above. Same rationale -- the
 // operator wants to run autocal tests in different signal modes
 // (RGB 10-bit full, RGB 10-bit limited, YCbCr 4:4:4 limited) without
 // being forced to switch to YCbCr 4:4:4 10-bit limited.
 if(meterLgAutoCalTransportReady()&&!hasUnsavedSettings()) return true;
 return true;
}
// Display a patch on PGenerator without reading
function meterMeasurementPatchSignalRange(){
 if(meterLgGreyscaleUsesExtendedSdr(meterActiveSeriesPoints)) return meterIsLimitedRange()?'1':'2';
 if(meterLgGreyscaleUsesLegalSdrDdcCodes(meterActiveSeriesPoints)) return meterIsLimitedRange()?'1':'2';
 if(meterGreyscaleUsesFullSourceRange()) return '2';
 return null;
}

async function meterDisplayPatch(step,options){
	 const displayToken=++meterPatternDisplayToken;
	 if(!meterEnsureAppliedGeneratorSettings()) return;
	 const freshStep=(options&&options.fresh===false)?step:(meterFreshSeriesStep(step)||step);
	 if(!freshStep) return;
	 if(displayToken!==meterPatternDisplayToken) return;
	 // A calibration patch supersedes any diagnostic pattern on the wire, so
	 // clear the highlighted Diagnostic Patterns button -- otherwise it stays
	 // lit as if it were still displayed after switching to Calibration.
	 if(typeof activePattern!=='undefined'&&activePattern!=null) clearActive();
	 meterCurrentPatchStep=freshStep;
	 const psize=getMeterPatchSize();
 const signalRange=meterMeasurementPatchSignalRange();
	 const payload=meterMeasurementSignalContext({name:'patch',r:freshStep.r,g:freshStep.g,b:freshStep.b,size:psize,input_max:meterStepInputMax(freshStep),signal_range:signalRange||undefined,pattern_session:String(displayToken)});
	 if(options&&options.allowAfterStop) payload.allow_after_stop=true;
	 if(displayToken!==meterPatternDisplayToken) return;
	 const endpoint=meterCalibrationReadPatternProvider()==='companion'?'/api/icc/companion/pattern':'/api/pattern';
	 const send=async()=>{
	  // A newer click supersedes this one before it reaches the generator.
	  // Serializing writes also prevents a slow older HTTP request from
	  // arriving after the current color and replacing it on screen.
	  if(displayToken!==meterPatternDisplayToken) return null;
	  const result=await fetchJSON(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},
   body:JSON.stringify(payload),_quiet:true,_timeoutMs:10000});
	  if(result&&result.status==='error') toast(result.message||'Could not display the patch',true);
	  return result;
	 };
	 meterPatternDisplayQueue=meterPatternDisplayQueue.catch(()=>null).then(send);
	 return meterPatternDisplayQueue;
}

