function meterFullAutoCalHdrWorkflowActive(){
 // A DV run is still an HDR20-rail workflow for any consumer of this flag
 // (tone-map upload gating, HDR-style prompt copy, ...). The collapse
 // forced DV into the SDR branch wherever this was checked (2026-07-24).
 const cfgMode=String((meterFullAutoCalConfig&&meterFullAutoCalConfig.signalMode)||'').toLowerCase();
 const reportMode=String((meterFullAutoCalReportData&&meterFullAutoCalReportData.signal_mode)||'').toLowerCase();
 const requested=String((typeof getVal==='function'?getVal('signal_mode'):'')||'').toLowerCase()
  ||((typeof meterLgAutoCalRequestedSignalMode==='function')?String(meterLgAutoCalRequestedSignalMode()||'').toLowerCase():'');
 return cfgMode==='hdr10'||cfgMode==='dv'||reportMode==='hdr10'||reportMode==='dv'||requested==='hdr10'||requested==='dv';
}

function meterFullAutoCalToneMapPeakLuminance(status){
 const candidates=[
  status&&status.hdr_tone_map_peak_luminance,
  status&&status.hdr20_1d_tonemap_peak_luminance,
  meterFullAutoCalResults&&meterFullAutoCalResults.first&&meterFullAutoCalResults.first.hdr20_1d_tonemap_peak_luminance,
  status&&status.peak_headroom_luminance,
  status&&status.calibrated_white_luminance,
  status&&status.target_luminance,
  meterFullAutoCalResults&&meterFullAutoCalResults.first&&meterFullAutoCalResults.first.peak_headroom_luminance,
  meterFullAutoCalResults&&meterFullAutoCalResults.first&&meterFullAutoCalResults.first.calibrated_white_luminance,
  meterFullAutoCalResults&&meterFullAutoCalResults.first&&meterFullAutoCalResults.first.target_luminance,
  meterFullAutoCalConfig&&meterFullAutoCalConfig.headroomY,
  meterFullAutoCalConfig&&meterFullAutoCalConfig.targetY
 ];
 for(const value of candidates){
  const n=Number(value);
  if(Number.isFinite(n)&&n>0) return n;
 }
 return null;
}

// =============================================================================
// HDR10 tone-map wizard prompt
// -----------------------------------------------------------------------------
// The reference-style HDR greyscale autocal measures 100% white AFTER the 1D LUT
// commit, before uploading the tone map. To match that, the backend now sets
// hdr20_1d_tonemap_pending=true in status instead of uploading inline. The
// wizard prompts the operator, does a fresh 100% white read, and uploads the
// tone map with that freshly measured peak.
//
// Test plan (manual):
//   - SDR greyscale autocal      -> no prompt, no upload (signalMode !== hdr10)
//   - HDR10 greyscale autocal    -> prompt shown, fresh peak read, Upload performs /api/lg/hdr-tone-map/upload
//   - HDR10 greyscale Skip       -> choice recorded in report
//   - HDR10 full autocal         -> prompt shown at end of fullWorkflow (chained before completion overlay)
//   - Modal click-outside / X    -> treated as Skip (returns false)
//   - Meter not detected         -> modal shows "could not measure" warning, skipped
//   - hdr20_1d_tonemap_upload_enabled=false in request body (explicit) -> no prompt, no upload (kill switch)
// =============================================================================
const METER_HDR_TONEMAP_PROMPT_KEY='meterHdrToneMapPromptChoice';

function meterShowChoiceModal(options){
 const opts=options||{};
 return new Promise(resolve=>{
  const existing=document.getElementById('meterAutoCalChoiceModal');
  if(existing) existing.remove();
  const root=document.createElement('div');
  root.id='meterAutoCalChoiceModal';
  root.setAttribute('data-meter-autocal-choice','1');
  root.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:100001;display:flex;align-items:center;justify-content:center;padding:20px;box-sizing:border-box';
  const card=document.createElement('div');
  card.style.cssText='background:var(--panel,#0f1320);border:1px solid var(--border,#1d2230);border-radius:10px;max-width:480px;width:100%;padding:20px;color:var(--text,#e3e6ef);box-shadow:0 18px 60px rgba(0,0,0,0.6);font-family:inherit';
  const title=document.createElement('div');
  title.style.cssText='font-size:1.0rem;font-weight:700;margin-bottom:10px;color:var(--text,#e3e6ef)';
  title.textContent=String(opts.title||'Confirm');
  const body=document.createElement('div');
  body.style.cssText='font-size:.85rem;color:var(--text2,#a8b0c0);line-height:1.5;margin-bottom:14px;white-space:pre-line';
  body.textContent=String(opts.body||'');
  const checks=Array.isArray(opts.checkboxes)?opts.checkboxes:[];
  const checkInputs={};
  const checkHost=document.createElement('div');
  checkHost.style.cssText='display:grid;gap:8px;margin-bottom:16px';
  checks.forEach(c=>{
   if(!c||!c.id) return;
   const lab=document.createElement('label');
   lab.style.cssText='display:flex;align-items:flex-start;gap:8px;font-size:.8rem;color:var(--text,#e3e6ef);cursor:pointer;line-height:1.4';
   const inp=document.createElement('input');
   inp.type='checkbox';
   inp.checked=c.checked!==false;
   inp.style.cssText='margin-top:3px;accent-color:var(--accent,#5b7fff)';
   lab.appendChild(inp);
   const span=document.createElement('span');
   span.textContent=String(c.label||c.id);
   lab.appendChild(span);
   checkHost.appendChild(lab);
   checkInputs[c.id]=inp;
  });
  const radios=Array.isArray(opts.radios)?opts.radios:[];
  const radioInputs={};
  const radioHost=document.createElement('div');
  radioHost.style.cssText='display:grid;gap:10px;margin-bottom:16px';
  radios.forEach(g=>{
   if(!g||!g.id||!Array.isArray(g.options)||!g.options.length) return;
   const group=document.createElement('div');
   group.style.cssText='display:grid;gap:6px';
   if(g.label){
    const gl=document.createElement('div');
    gl.style.cssText='font-size:.72rem;color:var(--text2);text-transform:uppercase;letter-spacing:.04em';
    gl.textContent=String(g.label);
    group.appendChild(gl);
   }
   const name='meterChoiceRadio_'+g.id;
   let first=true;
   g.options.forEach(opt=>{
    if(!opt||opt.value==null) return;
    const lab=document.createElement('label');
    lab.style.cssText='display:flex;align-items:flex-start;gap:8px;font-size:.8rem;color:var(--text,#e3e6ef);cursor:pointer;line-height:1.4';
    const inp=document.createElement('input');
    inp.type='radio';
    inp.name=name;
    inp.value=String(opt.value);
    inp.checked=opt.checked===true||(opt.checked==null&&first);
    first=false;
    inp.style.cssText='margin-top:3px;accent-color:var(--accent,#5b7fff)';
    lab.appendChild(inp);
    const span=document.createElement('span');
    span.textContent=String(opt.label!=null?opt.label:opt.value);
    lab.appendChild(span);
    group.appendChild(lab);
    if(!radioInputs[g.id]) radioInputs[g.id]=[];
    radioInputs[g.id].push(inp);
   });
   radioHost.appendChild(group);
  });
  const row=document.createElement('div');
  row.style.cssText='display:flex;gap:10px;justify-content:flex-end;flex-wrap:wrap';
  const cancelBtn=document.createElement('button');
  cancelBtn.className='btn btn-sm btn-secondary';
  cancelBtn.textContent=String(opts.cancelLabel||'Skip');
  const acceptBtn=document.createElement('button');
  acceptBtn.className='btn btn-sm btn-primary';
  acceptBtn.textContent=String(opts.acceptLabel||'OK');
  row.appendChild(cancelBtn);
  row.appendChild(acceptBtn);
  card.appendChild(title);
  card.appendChild(body);
  if(radios.length) card.appendChild(radioHost);
  if(checks.length) card.appendChild(checkHost);
  card.appendChild(row);
  root.appendChild(card);
  document.body.appendChild(root);
  let resolved=false;
  const cleanup=(value)=>{
   if(resolved) return;
   resolved=true;
   try{ document.removeEventListener('keydown',onKey,true); }catch(e){}
   try{ root.remove(); }catch(e){}
   resolve(value);
  };
  acceptBtn.onclick=()=>{
   if(!checks.length&&!radios.length){ cleanup(true); return; }
   const out={accepted:true};
   Object.keys(checkInputs).forEach(id=>{ out[id]=!!(checkInputs[id]&&checkInputs[id].checked); });
   Object.keys(radioInputs).forEach(id=>{
    const list=radioInputs[id]||[];
    const sel=list.find(inp=>inp&&inp.checked);
    out[id]=sel?String(sel.value):'';
   });
   cleanup(out);
  };
  cancelBtn.onclick=()=>cleanup(false);
  root.onclick=(ev)=>{ if(ev.target===root) cleanup(false); };
  function onKey(ev){ if(ev.key==='Escape') cleanup(false); }
  document.addEventListener('keydown',onKey,true);
  try{ acceptBtn.focus(); }catch(e){}
 });
}

